#include <stdio.h>

/* teste do desafio enquadra — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Fase VALOR: o teste declara os PROTOTIPOS das tres caixas do aluno e
   compara o VALOR DEVOLVIDO por cada uma. O ultimo cenario exercita as duas
   caixas internas direto — elas precisam existir para enquadra chamar. */

/* prototipos das funcoes do aluno (o teste declara o que exercita) */
int maior(int a, int b);
int menor(int a, int b);
int enquadra(int x, int min, int max);

SM_TEST(o_cinco_cabe_na_faixa) {
    checa_int("5 na faixa 0..10 fica 5", enquadra(5, 0, 10), 5,
              "5 esta dentro da faixa: nem o piso nem o teto mexem nele");
}

SM_TEST(o_quinze_encosta_no_teto) {
    checa_int("15 na faixa 0..10 vira 10", enquadra(15, 0, 10), 10,
              "15 passa do teto: menor(15, 10) devolve o teto");
}

SM_TEST(o_um_sobe_para_o_piso) {
    checa_int("1 na faixa 2..8 vira 2", enquadra(1, 2, 8), 2,
              "1 esta abaixo do piso: maior(1, 2) devolve o piso");
}

SM_TEST(as_caixas_internas_respondem_sozinhas) {
    checa_int("o maior de 3 e 9 e 9", maior(3, 9), 9,
              "maior devolve o maior dos dois numeros que recebeu");
    checa_int("o menor de 3 e 9 e 3", menor(3, 9), 3,
              "menor devolve o menor dos dois numeros que recebeu");
}

solutionCode:
int maior(int a, int b) {
    if (a >= b) {
        return a;
    }
    return b;
}

int menor(int a, int b) {
    if (a <= b) {
        return a;
    }
    return b;
}

int enquadra(int x, int min, int max) {
    int comPiso = maior(x, min);
    return menor(comPiso, max);
}
